### AWS ECS Deployment

```bash
# Build and push to ECR
python _helpers/scripts/build_docker.py --docker-env=prod \
  --registry=123456789.dkr.ecr.us-east-1.amazonaws.com \
  --site-url=https://docs.mycompany.com \
  --push

# ECS Task Definition (example)
{
  "family": "eap-mkdocs-platform-prod",
  "networkMode": "awsvpc",
  "requiresCompatibilities": ["FARGATE"],
  "cpu": "256",
  "memory": "512",
  "executionRoleArn": "arn:aws:iam::account:role/ecsTaskExecutionRole",
  "containerDefinitions": [
    {
      "name": "eap-mkdocs-platform",
      "image": "707203271462.dkr.ecr.us-east-1.amazonaws.com/pfe-pg-dev-us1-cm-ecr-platform-shared:eap-mkdocs-platform-latest-production",
      "portMappings": [
        {
          "containerPort": 8080,
          "protocol": "tcp"
        }
      ],
      "healthCheck": {
        "command": ["CMD-SHELL", "curl -f http://localhost:8080/health || exit 1"],
        "interval": 30,
        "timeout": 5,
        "retries": 3,
        "startPeriod": 10
      },
      "logConfiguration": {
        "logDriver": "awslogs",
        "options": {
          "awslogs-group": "/ecs/eap-mkdocs-platform",
          "awslogs-region": "us-east-1",
          "awslogs-stream-prefix": "ecs"
        }
      }
    }
  ]
}
```
